import struct
import sys

import wgpu

SHADER = """
struct Params { count: u32, seed: u32, bins: u32, pad: u32 };

@group(0) @binding(0) var<uniform> params: Params;
@group(0) @binding(1) var<storage, read_write> hist: array<atomic<u32>, 256>;

var<workgroup> local_hist: array<atomic<u32>, 256>;

const WG: u32 = 256u;
const GROUPS: u32 = 256u;

@compute @workgroup_size(256)
fn main(@builtin(local_invocation_index) lid: u32,
        @builtin(workgroup_id) wid: vec3<u32>) {
    atomicStore(&local_hist[lid], 0u);
    workgroupBarrier();

    let stride = WG * GROUPS;
    var i = wid.x * WG + lid;
    loop {
        if (i >= params.count) { break; }
        let a = ((i % 40000u) * 1597u + params.seed + 51749u) % 40000u;
        let b = (a * a + a * 37u + 11u) % 40009u;
        let c = (b * 613u + 7919u) % 40009u;
        let d = (c + (i / 40000u) * 7919u) % 40009u;
        let value = d % 1000u;
        let bin = value * params.bins / 1000u;
        atomicAdd(&local_hist[bin], 1u);
        i += stride;
    }
    workgroupBarrier();

    let n = atomicLoad(&local_hist[lid]);
    if (n != 0u) {
        atomicAdd(&hist[lid], n);
    }
}
"""


def main():
    with open(sys.argv[1]) as f:
        count, seed, bins = (int(x) for x in f.read().split())

    adapter = wgpu.gpu.request_adapter_sync(power_preference="high-performance")
    device = adapter.request_device_sync()

    module = device.create_shader_module(code=SHADER)
    params = device.create_buffer_with_data(
        data=struct.pack("<4I", count, seed, bins, 0),
        usage=wgpu.BufferUsage.UNIFORM,
    )
    hist = device.create_buffer(
        size=256 * 4,
        usage=wgpu.BufferUsage.STORAGE
        | wgpu.BufferUsage.COPY_SRC
        | wgpu.BufferUsage.COPY_DST,
    )
    readback = device.create_buffer(
        size=256 * 4,
        usage=wgpu.BufferUsage.MAP_READ | wgpu.BufferUsage.COPY_DST,
    )
    device.queue.write_buffer(hist, 0, bytes(256 * 4))

    layout = device.create_bind_group_layout(
        entries=[
            {
                "binding": 0,
                "visibility": wgpu.ShaderStage.COMPUTE,
                "buffer": {"type": wgpu.BufferBindingType.uniform},
            },
            {
                "binding": 1,
                "visibility": wgpu.ShaderStage.COMPUTE,
                "buffer": {"type": wgpu.BufferBindingType.storage},
            },
        ]
    )
    pipeline = device.create_compute_pipeline(
        layout=device.create_pipeline_layout(bind_group_layouts=[layout]),
        compute={"module": module, "entry_point": "main"},
    )
    bind_group = device.create_bind_group(
        layout=layout,
        entries=[
            {"binding": 0, "resource": {"buffer": params}},
            {"binding": 1, "resource": {"buffer": hist}},
        ],
    )

    encoder = device.create_command_encoder()
    cpass = encoder.begin_compute_pass()
    cpass.set_pipeline(pipeline)
    cpass.set_bind_group(0, bind_group)
    cpass.dispatch_workgroups(256, 1, 1)
    cpass.end()
    encoder.copy_buffer_to_buffer(hist, 0, readback, 0, 256 * 4)
    device.queue.submit([encoder.finish()])

    readback.map_sync(wgpu.MapMode.READ)
    counts = struct.unpack("<256I", bytes(readback.read_mapped()))
    readback.unmap()

    out = [f"BIN {i} {counts[i]}" for i in range(bins)]
    out.append(f"TOTAL {count}")
    sys.stdout.write("\n".join(out) + "\n")


if __name__ == "__main__":
    main()
